<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Concerns\HasUuids;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;use Illuminate\Database\Eloquent\Relations\BelongsToMany;
class StandardListVersion extends Model {use HasUuids;public $incrementing=false;protected $keyType='string';protected $fillable=['standard_list_id','version_number','status','effective_from','effective_until','change_notes','published_by','published_at'];protected function casts():array{return ['effective_from'=>'date','effective_until'=>'date','published_at'=>'datetime'];}public function standardList():BelongsTo{return $this->belongsTo(StandardList::class);}public function products():BelongsToMany{return $this->belongsToMany(Product::class,'standard_list_items')->withPivot(['minimum_quantity','maximum_quantity','notes'])->withTimestamps();}public function publisher():BelongsTo{return $this->belongsTo(User::class,'published_by');}}
